CREATE TABLE stores(id text PRIMARY KEY,platform text NOT NULL CHECK(platform IN ('shopify','woocommerce')),domain text NOT NULL,allow_partial boolean NOT NULL DEFAULT false,allow_backorder boolean NOT NULL DEFAULT false,reconciled_at timestamptz);
CREATE TABLE integration_events(id uuid PRIMARY KEY,store_id text NOT NULL REFERENCES stores,external_event_id text NOT NULL,topic text NOT NULL,correlation_id uuid NOT NULL,payload jsonb NOT NULL,payload_hash text NOT NULL,normalized jsonb,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','done','ignored','quarantined','dead')),attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),leased_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(store_id,external_event_id));
CREATE INDEX event_queue ON integration_events(next_attempt_at) WHERE status IN ('pending','processing');
CREATE TABLE orders(id uuid PRIMARY KEY,store_id text NOT NULL REFERENCES stores,external_id text NOT NULL,state text NOT NULL CHECK(state IN ('RECEIVED','VALIDATED','AWAITING_PAYMENT','STOCK_RESERVED','PARTIALLY_ALLOCATED','BACKORDERED','SHIPPING_QUOTED','READY_FOR_FULFILLMENT','FULFILLED','CANCELLED','FAILED')),currency char(3) NOT NULL,total numeric(20,6) NOT NULL CHECK(total>=0),payment_status text NOT NULL,fulfillment_status text NOT NULL,source_updated_at timestamptz NOT NULL,current_event_id uuid NOT NULL REFERENCES integration_events,normalized jsonb NOT NULL,revision int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(store_id,external_id));
CREATE TABLE products(id bigserial PRIMARY KEY,sku text UNIQUE NOT NULL,variant text,stocked boolean NOT NULL DEFAULT true,weight_kg numeric(12,6) CHECK(weight_kg>0),length_cm numeric CHECK(length_cm>0),width_cm numeric CHECK(width_cm>0),height_cm numeric CHECK(height_cm>0));
CREATE TABLE sku_aliases(store_id text NOT NULL REFERENCES stores,alias text NOT NULL,product_id bigint NOT NULL REFERENCES products,PRIMARY KEY(store_id,alias));
CREATE TABLE order_items(id bigserial PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders ON DELETE CASCADE,line_id text NOT NULL,product_id bigint REFERENCES products,sku text,variant text,quantity int NOT NULL CHECK(quantity>0),price numeric(20,6) NOT NULL CHECK(price>=0),stocked boolean NOT NULL,raw jsonb NOT NULL,UNIQUE(order_id,line_id));
CREATE TABLE warehouses(id text PRIMARY KEY,name text NOT NULL,priority int NOT NULL,address jsonb NOT NULL,countries text[] NOT NULL,source text NOT NULL DEFAULT 'local-postgres');
CREATE TABLE inventory_balances(product_id bigint NOT NULL REFERENCES products,warehouse_id text NOT NULL REFERENCES warehouses,on_hand int NOT NULL CHECK(on_hand>=0),reserved int NOT NULL DEFAULT 0 CHECK(reserved>=0),safety_stock int NOT NULL DEFAULT 0 CHECK(safety_stock>=0),incoming int NOT NULL DEFAULT 0 CHECK(incoming>=0),snapshot_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(product_id,warehouse_id),CHECK(reserved<=on_hand));
CREATE TABLE inventory_reservations(id bigserial PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders,revision int NOT NULL,product_id bigint NOT NULL,warehouse_id text NOT NULL,quantity int NOT NULL CHECK(quantity>0),status text NOT NULL CHECK(status IN ('held','confirmed','released','expired','consumed')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(product_id,warehouse_id) REFERENCES inventory_balances,UNIQUE(order_id,revision,product_id,warehouse_id));
CREATE INDEX reservations_expiring ON inventory_reservations(expires_at) WHERE status IN ('held','confirmed');
CREATE TABLE inventory_movements(id bigserial PRIMARY KEY,order_id uuid REFERENCES orders,reservation_id bigint REFERENCES inventory_reservations,product_id bigint NOT NULL REFERENCES products,warehouse_id text NOT NULL REFERENCES warehouses,kind text NOT NULL,quantity int NOT NULL,event_id uuid REFERENCES integration_events,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reorder_rules(product_id bigint NOT NULL,warehouse_id text NOT NULL,reorder_point int NOT NULL CHECK(reorder_point>=0),target_stock int NOT NULL CHECK(target_stock>=reorder_point),supplier text NOT NULL,lead_days int NOT NULL CHECK(lead_days>=0),minimum_order int NOT NULL CHECK(minimum_order>0),pack_multiple int NOT NULL CHECK(pack_multiple>0),outstanding int NOT NULL DEFAULT 0 CHECK(outstanding>=0),PRIMARY KEY(product_id,warehouse_id),FOREIGN KEY(product_id,warehouse_id) REFERENCES inventory_balances);
CREATE TABLE reorder_alerts(id bigserial PRIMARY KEY,product_id bigint NOT NULL REFERENCES products,warehouse_id text NOT NULL REFERENCES warehouses,available int NOT NULL,threshold int NOT NULL,recommended int NOT NULL CHECK(recommended>=0),status text NOT NULL CHECK(status IN ('open','resolved','ordered')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX reorder_open ON reorder_alerts(product_id,warehouse_id) WHERE status IN ('open','ordered');
CREATE TABLE shipping_quotes(id bigserial PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders,revision int NOT NULL,warehouse_id text NOT NULL REFERENCES warehouses,rate_id text NOT NULL,currency char(3) NOT NULL,amount numeric(20,6) NOT NULL CHECK(amount>=0),carrier text NOT NULL,service text NOT NULL,estimated_days int,address_validation text NOT NULL,selected boolean NOT NULL DEFAULT false,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,revision,warehouse_id,rate_id));
CREATE UNIQUE INDEX one_selected_rate ON shipping_quotes(order_id,revision,warehouse_id) WHERE selected;
CREATE TABLE fulfillment_events(id bigserial PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders,event_id uuid NOT NULL REFERENCES integration_events,state text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,event_id,state));
CREATE TABLE workflow_audit_logs(id bigserial PRIMARY KEY,order_id uuid REFERENCES orders,event_id uuid REFERENCES integration_events,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_order ON workflow_audit_logs(order_id,created_at);
CREATE TABLE integration_errors(id bigserial PRIMARY KEY,event_id uuid REFERENCES integration_events,correlation_id text,category text NOT NULL,message text NOT NULL,details jsonb NOT NULL DEFAULT '{}',resolved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_outbox(id bigserial PRIMARY KEY,dedupe_key text UNIQUE NOT NULL,severity text NOT NULL CHECK(severity IN ('info','warning','critical')),correlation_id text NOT NULL,category text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','dead')),attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),leased_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE INDEX notification_queue ON notification_outbox(next_attempt_at) WHERE status IN ('pending','sending');
